// ── SYNONYM GROUPS (Final Exam "비슷한 말" questions) ──
// Every word in a group is in the TOPIK I list; each word maps to the others in its group.
const SYNONYM_GROUPS = [
  ['아주','매우'], ['정말','진짜'], ['회사','직장'], ['이름','성함'],
  ['집','댁'], ['곧','금방'], ['모두','전부','다'], ['같이','함께'],
  ['항상','늘'], ['값','가격'], ['아름답다','예쁘다'], ['재미있다','즐겁다'],
  ['어렵다','힘들다'], ['끝나다','마치다'], ['자다','주무시다'], ['주다','드리다']
];
const SYNONYMS = {};
SYNONYM_GROUPS.forEach(grp=>grp.forEach(w=>{ SYNONYMS[w] = grp.filter(x=>x!==w); }));


